import java.util.Objects;

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    String strMod = str;
    String suffixMod = suffix;
    if (ignoreCase) {
        strMod = str.toLowerCase();
        suffixMod = suffix.toLowerCase();
    }
    return strMod.endsWith(suffixMod);
}

