private class DoublyLinkedList<E> {
    private ListNodeImpl<E> head;
    private ListNodeImpl<E> tail;

    public void addListNode(ListNodeImpl<E> node) {
        if (node == null) return;
        if (tail == null) {
            head = tail = node;
        } else {
            tail.next = node;
            node.prev = tail;
            tail = node;
        }
    }

    public void removeListNode(ListNodeImpl<E> node) {
        if (node == null) return;
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }
        node.prev = node.next = null;
    }

    public List<ListNodeImpl<E>> getAllListNodes() {
        List<ListNodeImpl<E>> nodes = new ArrayList<>();
        ListNodeImpl<E> current = head;
        while (current != null) {
            nodes.add(current);
            current = current.next;
        }
        return nodes;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    List<ListNodeImpl<E>> nodes = list.getAllListNodes();
    for (ListNodeImpl<E> node : nodes) {
        list.removeListNode(node);
        addListNode(node);
    }
}

