class Node {
    private List<Edge> edges;
    private int id;

    public Node(int id) {
        this.id = id;
        this.edges = new ArrayList<>();
    }

    public void addEdge(Edge edge) {
        edges.add(edge);
    }

    public Edge edgeToNext() {
        // Assuming we have a way to determine the next node, for this example, let's assume
        // the next node is the one with the smallest id greater than this node's id.
        Node nextNode = null;
        for (Edge edge : edges) {
            Node otherNode = edge.getOtherNode(this);
            if (nextNode == null || otherNode.getId() < nextNode.getId()) {
                nextNode = otherNode;
            }
        }
        return nextNode != null ? new Edge(this, nextNode) : null;
    }

    public int getId() {
        return id;
    }
}

