    private Node node1;
    private Node node2;

    public Edge(Node node1, Node node2) {
        this.node1 = node1;
        this.node2 = node2;
    }

    public Node getOtherNode(Node node) {
        return node.equals(node1) ? node2 : node1;
    }
}

