import com.google.common.primitives.Ints;

public class SparseMatrix {
    private int[][] matrix;

    public SparseMatrix(int[][] matrix) {
        this.matrix = matrix;
    }

    public int nonZeros(int row) {
        if (row < 0 || row >= matrix.length) {
            throw new IllegalArgumentException("Row index out of bounds");
        }
        int count = 0;
        for (int value : matrix[row]) {
            if (value != 0) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[][] matrix = {
            {0, 2, 0, 4},
            {5, 0, 0, 0},
            {0, 0, 6, 0}
        };
        SparseMatrix sparseMatrix = new SparseMatrix(matrix);
        System.out.println(sparseMatrix.nonZeros(0)); // Output: 2
        System.out.println(sparseMatrix.nonZeros(1)); // Output: 1
        System.out.println(sparseMatrix.nonZeros(2)); // Output: 1
    }
}

