import java.io.IOException;
import java.io.InputStream;

public class ProtocolBufferParser {
    private InputStream input;

    public ProtocolBufferParser(InputStream input) {
        this.input = input;
    }

    public int readTag() throws IOException {
        int b = input.read();
        if (b == -1) {
            return 0;
        }
        return b;
    }

    public static void main(String[] args) {
        // Example usage
        byte[] data = {0x08}; // Example data containing a single byte tag
        ProtocolBufferParser parser = new ProtocolBufferParser(new java.io.ByteArrayInputStream(data));
        try {
            int tag = parser.readTag();
            System.out.println("Read tag: " + tag);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

